"""No AI/Muse branding or watermarks in shipped code, docs, or outputs."""

import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
BANNED = [
    "Muse", "Anthropic", "Claude", "AI-generated", "generated by AI",
    "as an AI",
]
# RESEARCH.md is a research log: it may name models and repos it surveyed.
SKIP_DIRS = {"docs"}
SKIP_FILES = {"test_branding.py"}


def _files():
    for p in ROOT.rglob("*"):
        if not p.is_file():
            continue
        if p.suffix not in {".py", ".md", ".toml", ".txt", ".yml", ".json"}:
            continue
        if any(part in SKIP_DIRS for part in p.relative_to(ROOT).parts):
            continue
        if p.name in SKIP_FILES or p.name == "LICENSE":
            continue
        if ".venv" in p.parts or "__pycache__" in p.parts:
            continue
        yield p


def test_no_branding():
    bad = []
    for p in _files():
        text = p.read_text(errors="ignore")
        for token in BANNED:
            if token.lower() in text.lower():
                bad.append(f"{p.relative_to(ROOT)}: {token!r}")
    assert not bad, "; ".join(bad)
